import shutil, pathlib, json
import pandas as pd
repo = pathlib.Path('repo')
# 1) restore author data + pinned requirements
shutil.copytree('state/original_data', repo/'data', dirs_exist_ok=True)
shutil.copy('state/requirements-authors-pinned.txt', repo/'requirements.txt')
# remove stray quick-run artifacts if any
for p in [repo/'trimcal_artifact.zip', repo/'scripts'/'__pycache__']:
    if p.is_dir(): shutil.rmtree(p)
    elif p.exists(): p.unlink()
print('restored. requirements.txt:')
print((repo/'requirements.txt').read_text())
# 2) author-CSV cross-check aggregates
df = pd.read_csv(repo/'data'/'main_results.csv')
noisy = df[df.noise_rate > 0]
g = noisy[noisy.method == 'gated_lwcal']
agg = {
  'n_rows_total': int(len(df)),
  'n_gated_noisy_cells': int(len(g)),
  'gated_lwcal': {'ece': float(g.ece.mean()), 'nll': float(g.nll.mean()), 'brier': float(g.brier.mean())},
}
for m in ['raw','isotonic','lwcal','platt','beta']:
    sub = noisy[noisy.method == m]
    agg[m] = {'ece': float(sub.ece.mean()), 'nll': float(sub.nll.mean()), 'brier': float(sub.brier.mean())}
sym = noisy[noisy.noise_mode=='symmetric']; asym = noisy[noisy.noise_mode=='asymmetric']
agg['symmetric'] = {m: {'ece': float(sym[sym.method==m].ece.mean()), 'nll': float(sym[sym.method==m].nll.mean())} for m in ['raw','isotonic','lwcal','gated_lwcal']}
agg['asymmetric'] = {m: {'ece': float(asym[asym.method==m].ece.mean()), 'nll': float(asym[asym.method==m].nll.mean())} for m in ['raw','isotonic','lwcal','gated_lwcal']}
pathlib.Path('state/author_aggregates.json').write_text(json.dumps(agg, indent=2))
print(json.dumps(agg, indent=2))

